// Traceability between the TB diagram and the generated code (docs/08 R20) —
// the PURE part (no vscode), tested in Node (scripts/test-trace.mjs).
//
// Probed on quick-uvm 1.1.0 (Oct 2026, the yapp_buffer tutorial bench): the
// generated files carry NO anchor with the element id — only the header
// `// This File: <name>` / `// Generated by: QuickUVM`. So the two directions
// rest on two different sources:
//   - element <-> OWNED file is EXACT: the manifest (`owner` -> files, docs/07
//     Track A), one owner per file of an agent / scoreboard / vseq / test /
//     probe set, inferred elements included (`scoreboard:sbd` in implicit mode);
//   - element <-> lines of an AGGREGATE file (env, tb_top, base_test, env_cfg,
//     virtual sequencer, tb_pkg) is APPROXIMATE: the generator derives every
//     identifier from the element's name and from the stems of its owned files
//     (`cmd_agnt`, `cmd_if_inst`, `cmd_cov_h`, `pkt_sb`, `yapp_buffer_scoreboard`),
//     so a word-boundary pattern on those finds the lines — the row's own caveat
//     ("without anchors from the generator, traceability is approximate").

import { ownerToNodeId, type Manifest } from "./genstate";
import type { ResolvedConfig } from "./resolved";

/** the basename of a generated file path (the manifest lists plain names) */
export function baseName(file: string): string {
  const i = Math.max(file.lastIndexOf("/"), file.lastIndexOf("\\"));
  return i >= 0 ? file.slice(i + 1) : file;
}

/** the manifest OWNER of a generated file (`agent:cmd`, `scoreboard:pkt_sb`,
 *  `aggregate`, ...), or null when the manifest does not list it */
export function ownerOfFile(manifest: Manifest, file: string): string | null {
  const name = baseName(file);
  for (const el of manifest.elements) {
    if (el.files.some((f) => f.file === name)) {
      return el.owner;
    }
  }
  return null;
}

/** an owner's kind and name: `agent:cmd` -> {agent, cmd}; `probes` -> {probes, ""} */
export function ownerParts(owner: string): { kind: string; name: string } {
  const i = owner.indexOf(":");
  return i < 0 ? { kind: owner, name: "" } : { kind: owner.slice(0, i), name: owner.slice(i + 1) };
}

/** the human label of an owner for a lens / a report line */
export function ownerLabel(owner: string): string {
  const { kind, name } = ownerParts(owner);
  switch (kind) {
    case "agent":
      return `agent ${name}`;
    case "scoreboard":
      return `scoreboard ${name}`;
    case "vseq":
      return `virtual sequence ${name}`;
    case "test":
      return `test ${name}`;
    case "probes":
      return "probes";
    case "register_model":
      return "register model";
    case "vip":
      return "VIP";
    case "aggregate":
      return "whole-config files";
    default:
      return owner;
  }
}

function stemsOf(manifest: Manifest, owner: string): string[] {
  const out: string[] = [];
  for (const el of manifest.elements) {
    if (el.owner === owner) {
      for (const f of el.files) {
        const dot = f.file.lastIndexOf(".");
        out.push(dot > 0 ? f.file.slice(0, dot) : f.file);
      }
    }
  }
  return out;
}

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const ABBREV: Record<string, string> = { driver: "drv", monitor: "mon", sequencer: "sqr" };

/**
 * The pattern that finds a diagram element's generated identifiers in an
 * AGGREGATE file: its name, the stems of its owned files, and the handles the
 * generator derives from them (`<word>` or `<word>_<suffix>`, word-bounded).
 * Null for the elements that own no generated identifier (`env`, `dut`, the
 * boundary flags, an unknown id).
 */
export function tracePattern(manifest: Manifest, nodeId: string): RegExp | null {
  const words: string[] = [];
  const internal = /^agent:([^:]+):u\.([a-z_]+)$/.exec(nodeId);
  if (internal) {
    const [, a, part] = internal;
    words.push(`${a}_${part}`);
    if (ABBREV[part]) {
      words.push(`${a}_${ABBREV[part]}`);
    }
  } else if (nodeId.startsWith("cov:")) {
    words.push(`${nodeId.slice("cov:".length)}_cov`);
  } else if (/^agent:[^:]+$/.test(nodeId)) {
    const a = nodeId.slice("agent:".length);
    words.push(a, ...stemsOf(manifest, nodeId));
  } else if (nodeId.startsWith("sb:") || nodeId.startsWith("xsb:")) {
    const n = nodeId.slice(nodeId.indexOf(":") + 1);
    words.push(n, ...stemsOf(manifest, `scoreboard:${n}`));
  } else if (nodeId === "vsqr") {
    words.push("vsqr");
    for (const el of manifest.elements) {
      if (el.owner.startsWith("vseq:")) {
        words.push(...stemsOf(manifest, el.owner));
      }
    }
  } else if (nodeId === "probes") {
    words.push("probe", ...stemsOf(manifest, "probes"));
  } else if (nodeId.startsWith("sub:")) {
    words.push(nodeId.slice("sub:".length));
  } else {
    return null;
  }
  const alts = [...new Set(words.filter(Boolean))].map(escapeRe);
  if (nodeId === "vsqr") {
    alts.push("(?:\\w+_)?virtual_sequencer"); // the class of the aggregate file itself
  }
  return new RegExp(`\\b(?:${alts.join("|")})(?:_\\w+)?\\b`);
}

/** the 0-based lines of `text` the pattern matches; comment-only lines are
 *  skipped (the file header names the file, a section comment names a kind) */
export function traceLines(text: string, pattern: RegExp): number[] {
  const out: number[] = [];
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^\s*\/\//.test(line)) {
      continue;
    }
    if (pattern.test(line)) {
      out.push(i);
    }
  }
  return out;
}

/** the generator supplied the element without a YAML entry (`quick-uvm resolve`) */
export function isInferred(resolved: ResolvedConfig | null | undefined, owner: string): boolean {
  if (!resolved) {
    return false;
  }
  const { kind, name } = ownerParts(owner);
  if (kind === "scoreboard") {
    return (resolved.analysis?.scoreboards ?? []).some((s) => s.name === name && s.origin === "inferred");
  }
  if (kind === "vseq") {
    return (resolved.virtual_sequences ?? []).some((v) => v.name === name && v.origin === "inferred");
  }
  if (kind === "test") {
    return (resolved.tests ?? []).some((t) => t.name === name && t.origin === "inferred");
  }
  return false;
}

export interface TraceLens {
  /** 0-based line */
  line: number;
  /** the diagram / verification-tree node to reveal */
  nodeId: string;
  owner: string;
  label: string;
  inferred: boolean;
}

/**
 * The lenses of a generated file: an OWNED file gets one at its top (its
 * element); an AGGREGATE file gets one per element at the first line that
 * mentions it; a file the manifest does not list, or an owner the diagram does
 * not draw (`test:`, `vip`, `register_model`), gets none.
 */
export function traceLenses(
  manifest: Manifest,
  file: string,
  text: string,
  resolved: ResolvedConfig | null | undefined
): TraceLens[] {
  const owner = ownerOfFile(manifest, file);
  if (!owner) {
    return [];
  }
  if (owner !== "aggregate") {
    const nodeId = ownerToNodeId(owner);
    return nodeId
      ? [{ line: 0, nodeId, owner, label: ownerLabel(owner), inferred: isInferred(resolved, owner) }]
      : [];
  }
  const out: TraceLens[] = [];
  for (const el of manifest.elements) {
    const nodeId = ownerToNodeId(el.owner);
    if (el.owner === "aggregate" || !nodeId) {
      continue;
    }
    // several vseq owners share the `vsqr` node: one lens, on the node's pattern
    if (out.some((l) => l.nodeId === nodeId)) {
      continue;
    }
    const pattern = tracePattern(manifest, nodeId);
    const first = pattern ? traceLines(text, pattern)[0] : undefined;
    if (first !== undefined) {
      out.push({
        line: first,
        nodeId,
        owner: el.owner,
        label: ownerLabel(el.owner),
        inferred: isInferred(resolved, el.owner),
      });
    }
  }
  return out.sort((a, b) => a.line - b.line);
}

/**
 * The traceability report (markdown): every element with its owned files and
 * their on-disk state, the elements the generator supplies without a YAML entry
 * (the "untraceable" list of the row — nothing in the YAML to go back to), and
 * the whole-config files. `present` = the files that exist on disk (null when
 * unknown: no flags).
 */
export function traceReport(
  manifest: Manifest,
  resolved: ResolvedConfig | null | undefined,
  present: ReadonlySet<string> | null,
  configName: string
): string {
  const flag = (f: string): string => (present ? (present.has(f) ? "✓ " : "○ ") : "");
  const files = (owner: string): string =>
    manifest.elements
      .filter((e) => e.owner === owner)
      .flatMap((e) => e.files.map((f) => `${flag(f.file)}\`${f.file}\``))
      .join(", ");
  const declared: string[] = [];
  const inferred: string[] = [];
  for (const el of manifest.elements) {
    if (el.owner === "aggregate") {
      continue;
    }
    const row = `| ${ownerLabel(el.owner)} | ${files(el.owner)} |`;
    (isInferred(resolved, el.owner) ? inferred : declared).push(row);
  }
  const lines: string[] = [
    `# Traceability — ${configName}`,
    "",
    `Layout \`${manifest.layout}\`, output \`${manifest.output_dir}\`` +
      (present ? " — ✓ on disk, ○ not generated yet" : "") +
      ".",
    "",
    "## Declared elements",
    "",
    "| Element | Generated files |",
    "|---|---|",
    ...declared,
    "",
    "## Inferred by quick-uvm — no YAML entry to trace back to",
    "",
  ];
  if (inferred.length) {
    lines.push(
      resolved?.analysis?.mode === "implicit"
        ? "The config has no `analysis:` key, so the generator wires these itself (implicit mode)."
        : "Supplied by the generator's defaults.",
      "",
      "| Element | Generated files |",
      "|---|---|",
      ...inferred
    );
  } else {
    lines.push("None.");
  }
  lines.push("", "## Whole-config files (co-regenerated on any structural change)", "", files("aggregate"), "");
  return lines.join("\n");
}
